1	/**
2	 * WikiEquipmentEnricher.ts
3	 *
4	 * Structured parser for RS Wiki Infobox templates and drop tables.
5	 * Extracts equipment bonuses, item metadata, monster stats, and complete
6	 * drop tables (including sub-table resolution) with respectful rate limiting.
7	 *
8	 * Sovereign Substrate: Semantic Enrichment Layer
9	 * Cache Authority: D:\sovereign\atlas\wiki\cache\
10	 *
11	 * Template Coverage:
12	 *   - {{Infobox Bonuses}}  → Equipment combat stats
13	 *   - {{Infobox Item}}     → Item metadata
14	 *   - {{Infobox Monster}}  → Monster/NPC stats
15	 *   - {{DropsLine}}        → Individual drop entries
16	 *   - {{Rare drop table}}, {{Gem drop table}}, etc. → Sub-table resolution
17	 */
18	
19	import { createLogger } from './logger.js';
20	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
21	import { join } from 'path';
22	
23	const logger = createLogger('WikiEquipmentEnricher');
24	
25	// ═══════════════════════════════════════════════════════
26	// Interfaces
27	// ═══════════════════════════════════════════════════════
28	
29	export interface WikiEquipmentBonuses {
30	    tier: number;
31	    slot: string;          // mainhand, off-hand, 2h, head, body, legs, feet, hands, back, neck, ring, ammo, pocket, shield
32	    class: string;         // melee, ranged, magic, necromancy, all, hybrid
33	    style: string;         // slash, stab, crush, none
34	    damage: number;
35	    accuracy: number;
36	    armour: number;
37	    lifeBonus: number;
38	    prayerBonus: number;
39	    attackSpeed: string;   // fastest, fast, average, slow, slowest
40	}
41	
42	export interface WikiItemMeta {
43	    name: string;
44	    examine: string;
45	    tradeable: boolean;
46	    stackable: boolean;
47	    members: boolean;
48	    weight: number;
49	    highAlch: number;
50	    lowAlch: number;
51	    /** Grand Exchange price in coins. 0 = not on GE or unknown. */
52	    geValue: number;
53	    quest: string;
54	    release: string;
55	}
56	
57	export interface WikiMonsterMeta {
58	    name: string;
59	    combatLevel: number;
60	    lifePoints: number;
61	    maxHit: number;
62	    weakness: string;
63	    slayerLevel: number;
64	    slayerCategory: string;
65	    aggressive: boolean;
66	    poisonous: boolean;
67	    attackStyle: string;
68	    members: boolean;
69	    experience: number;
70	    
71	    // March 2026 Combat Affinities
72	    defence: number;
73	    armour: number;
74	    affinityMelee: number;
75	    affinityRanged: number;
76	    affinityMagic: number;
77	    affinityNecromancy: number;
78	}
79	
80	export interface WikiDropEntry {
81	    itemName: string;
82	    quantity: string;       // "1", "1-3", "1 (noted)", etc.
83	    rarity: string;         // "Always", "Common", "Uncommon", "Rare", "Very rare", "1/128"
84	    isMembers: boolean;
85	    notes: string;
86	    /** Grand Exchange value in coins. 0 = not tradeable or unknown. Used by LootBeamRegistry. */
87	    geValue: number;
88	}
89	
90	export interface WikiDropTable {
91	    section: string;        // "Main", "Charms", "Tertiary", sub-table name
92	    entries: WikiDropEntry[];
93	}
94	
95	export interface WikiPageData {
96	    title: string;
97	    fetchedAt: number;
98	    bonuses: WikiEquipmentBonuses | null;
99	    itemMeta: WikiItemMeta | null;
100	    monsterMeta: WikiMonsterMeta | null;
101	    dropTables: WikiDropTable[];
102	    rawVariables: Record<string, string>;
103	}
104	
105	// ═══════════════════════════════════════════════════════
106	// WikiEquipmentEnricher — Singleton
107	// ═══════════════════════════════════════════════════════
108	
109	export class WikiEquipmentEnricher {
110	    private static instance: WikiEquipmentEnricher;
111	
112	    private readonly API_BASE = 'https://runescape.wiki/api.php';
113	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; respectful-soft-parse)';
114	    private readonly RATE_LIMIT_MS = 1500;
115	    private readonly CACHE_DIR: string;
116	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
117	
118	    private lastRequestTime = 0;
119	    private requestCount = 0;
120	
121	    private constructor() {
122	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
123	        this.ensureCacheDir();
124	    }
125	
126	    public static getInstance(): WikiEquipmentEnricher {
127	        if (!this.instance) {
128	            this.instance = new WikiEquipmentEnricher();
129	        }
130	        return this.instance;
131	    }
132	
133	    // ── Cache Layer ────────────────────────────────────────
134	
135	    private ensureCacheDir(): void {
136	        const dirs = [
137	            this.CACHE_DIR,
138	            join(this.CACHE_DIR, 'items'),
139	            join(this.CACHE_DIR, 'monsters'),
140	            join(this.CACHE_DIR, 'templates'),
141	            join(this.CACHE_DIR, 'wikitext')
142	        ];
143	        for (const dir of dirs) {
144	            if (!existsSync(dir)) {
145	                mkdirSync(dir, { recursive: true });
146	            }
147	        }
148	    }
149	
150	    private sanitizeFilename(name: string): string {
151	        return name.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').toLowerCase();
152	    }
153	
154	    private readCache(subdir: string, key: string): any | null {
155	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
156	        if (!existsSync(filePath)) return null;
157	
158	        try {
159	            const raw = readFileSync(filePath, 'utf8');
160	            const cached = JSON.parse(raw);
161	
162	            // TTL check
163	            if (cached._cachedAt && (Date.now() - cached._cachedAt) > this.CACHE_TTL_MS) {
164	                logger.debug({ key }, 'Cache expired, will re-fetch.');
165	                return null;
166	            }
167	
168	            return cached;
169	        } catch {
170	            return null;
171	        }
172	    }
173	
174	    private writeCache(subdir: string, key: string, data: any): void {
175	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
176	        try {
177	            writeFileSync(filePath, JSON.stringify({ ...data, _cachedAt: Date.now() }, null, 2), 'utf8');
178	        } catch (err) {
179	            logger.warn({ key, err }, 'Failed to write cache.');
180	        }
181	    }
182	
183	    // ── Rate Limiter ───────────────────────────────────────
184	
185	    private async throttle(): Promise<void> {
186	        const now = Date.now();
187	        const elapsed = now - this.lastRequestTime;
188	        if (elapsed < this.RATE_LIMIT_MS) {
189	            const delay = this.RATE_LIMIT_MS - elapsed;
190	            await new Promise(resolve => setTimeout(resolve, delay));
191	        }
192	        this.lastRequestTime = Date.now();
193	        this.requestCount++;
194	    }
195	
196	    // ── API Layer ──────────────────────────────────────────
197	
198	    /**
199	     * Fetch raw wikitext for a page. Checks disk cache first.
200	     */
201	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
202	        const cached = this.readCache('wikitext', pageTitle);
203	        if (cached?.wikitext) {
204	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
205	            return cached.wikitext;
206	        }
207	
208	        await this.throttle();
209	
210	        const params = new URLSearchParams({
211	            action: 'parse',
212	            format: 'json',
213	            page: pageTitle,
214	            prop: 'wikitext',
215	            origin: '*'
216	        });
217	
218	        try {
219	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
220	                headers: {
221	                    'User-Agent': this.USER_AGENT,
222	                    'Accept': 'application/json'
223	                },
224	                signal: AbortSignal.timeout(10000)
225	            });
226	
227	            if (!response.ok) {
228	                logger.warn({ title: pageTitle, status: response.status }, 'Wiki API non-OK response.');
229	                return null;
230	            }
231	
232	            const data = await response.json() as any;
233	            const wikitext = data.parse?.wikitext?.['*'] || null;
234	
235	            if (wikitext) {
236	                this.writeCache('wikitext', pageTitle, { wikitext });
237	                logger.info({ title: pageTitle, length: wikitext.length, request: this.requestCount }, 'Wikitext fetched.');
238	            }
239	
240	            return wikitext;
241	        } catch (err) {
242	            logger.error({ title: pageTitle, err }, 'Failed to fetch wikitext.');
243	            return null;
244	        }
245	    }
246	
247	    /**
248	     * Search for the canonical page title matching a query.
249	     */
250	    private async searchPage(query: string): Promise<string | null> {
251	        await this.throttle();
252	
253	        const params = new URLSearchParams({
254	            action: 'query',
255	            format: 'json',
256	            list: 'search',
257	            srsearch: query,
258	            srlimit: '1',
259	            origin: '*'
260	        });
261	
262	        try {
263	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
264	                headers: { 'User-Agent': this.USER_AGENT },
265	                signal: AbortSignal.timeout(10000)
266	            });
267	
268	            const data = await response.json() as any;
269	            return data.query?.search?.[0]?.title || null;
270	        } catch (err) {
271	            logger.error({ query, err }, 'Wiki search failed.');
272	            return null;
273	        }
274	    }
275	
276	    /**
277	     * Resolves a name to wikitext. Tries direct fetch, follows redirects, falls back to search.
278	     */
279	    private async getWikitextForName(name: string): Promise<string | null> {
280	        // Try direct page first
281	        let wikitext = await this.fetchWikitext(name);
282	
283	        // Follow #REDIRECT if the page is a redirect stub
284	        if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
285	            const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
286	            if (redirectMatch) {
287	                const redirectTarget = redirectMatch[1].trim();
288	                logger.info({ from: name, to: redirectTarget }, 'Following wiki redirect...');
289	                wikitext = await this.fetchWikitext(redirectTarget);
290	            }
291	        }
292	
293	        if (!wikitext) {
294	            // Fallback: search for the page
295	            const title = await this.searchPage(name);
296	            if (title && title !== name) {
297	                wikitext = await this.fetchWikitext(title);
298	                // Follow redirect on search result too
299	                if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
300	                    const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
301	                    if (redirectMatch) {
302	                        const redirectTarget = redirectMatch[1].trim();
303	                        logger.info({ from: title, to: redirectTarget }, 'Following wiki redirect (search fallback)...');
304	                        wikitext = await this.fetchWikitext(redirectTarget);
305	                    }
306	                }
307	            }
308	        }
309	
310	        return wikitext;
311	    }
312	
313	    // ── Template Parser ────────────────────────────────────
314	
315	    /**
316	     * Extract a single template's parameters from wikitext.
317	     * Handles nested templates via bracket-depth tracking.
318	     */
319	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
320	        const lowerText = wikitext.toLowerCase();
321	        const lowerName = templateName.toLowerCase();
322	
323	        let searchIdx = 0;
324	        let startIdx = -1;
325	
326	        while (searchIdx < lowerText.length) {
327	            const bracePos = lowerText.indexOf('{{', searchIdx);
328	            if (bracePos === -1) break;
329	
330	            let nameStart = bracePos + 2;
331	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
332	
333	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
334	                const afterName = lowerText[nameStart + lowerName.length];
335	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
336	                    startIdx = bracePos;
337	                    break;
338	                }
339	            }
340	            searchIdx = bracePos + 2;
341	        }
342	
343	        if (startIdx === -1) return null;
344	
345	        // Find matching closing }} using bracket depth
346	        let depth = 0;
347	        let endIdx = startIdx;
348	        for (let i = startIdx; i < wikitext.length - 1; i++) {
349	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
350	                depth++;
351	                i++;
352	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
353	                depth--;
354	                i++;
355	                if (depth === 0) {
356	                    endIdx = i + 1;
357	                    break;
358	                }
359	            }
360	        }
361	
362	        if (depth !== 0) return null;
363	
364	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
365	        const pipeIdx = fullContent.indexOf('|');
366	        if (pipeIdx === -1) return {};
367	
368	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
369	    }
370	
371	    /**
372	     * Extract ALL instances of a template from wikitext.
373	     * Critical for DropsLine parsing where each drop is a separate template call.
374	     */
375	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
376	        const results: Record<string, string>[] = [];
377	        const lowerText = wikitext.toLowerCase();
378	        const lowerName = templateName.toLowerCase();
379	        let searchIdx = 0;
380	
381	        while (searchIdx < lowerText.length) {
382	            const bracePos = lowerText.indexOf('{{', searchIdx);
383	            if (bracePos === -1) break;
384	
385	            let nameStart = bracePos + 2;
386	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
387	
388	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
389	                const afterName = lowerText[nameStart + lowerName.length];
390	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
391	                    // Find closing braces
392	                    let depth = 0;
393	                    let endIdx = bracePos;
394	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
395	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
396	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
397	                            depth--; i++;
398	                            if (depth === 0) { endIdx = i + 1; break; }
399	                        }
400	                    }
401	
402	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
403	                    const pipeIdx = fullContent.indexOf('|');
404	                    if (pipeIdx !== -1) {
405	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
406	                    }
407	
408	                    searchIdx = endIdx;
409	                    continue;
410	                }
411	            }
412	            searchIdx = bracePos + 2;
413	        }
414	
415	        return results;
416	    }
417	
418	    /**
419	     * Parse pipe-separated template parameters, respecting nested template depth.
420	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
421	     */
422	    private parseTemplateParams(text: string): Record<string, string> {
423	        const params: Record<string, string> = {};
424	        let depth = 0;
425	        let currentParam = '';
426	        let positionalIdx = 1;
427	
428	        for (let i = 0; i < text.length; i++) {
429	            const ch = text[i];
430	            const next = text[i + 1];
431	
432	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
433	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
434	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
435	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
436	            else if (ch === '|' && depth === 0) {
437	                this.assignParam(params, currentParam, positionalIdx);
438	                positionalIdx++;
439	                currentParam = '';
440	            } else {
441	                currentParam += ch;
442	            }
443	        }
444	
445	        // Last parameter
446	        if (currentParam.trim()) {
447	            this.assignParam(params, currentParam, positionalIdx);
448	        }
449	
450	        return params;
451	    }
452	
453	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
454	        const eqIdx = raw.indexOf('=');
455	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
456	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
457	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
458	            if (key) params[key] = value;
459	        } else {
460	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
461	        }
462	    }
463	
464	    /**
465	     * Strip wiki markup from a value (links, formatting, refs).
466	     */
467	    private cleanWikiMarkup(text: string): string {
468	        return text
469	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
470	            .replace(/'''?/g, '')                                // Bold/italic
471	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
472	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
473	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
474	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
475	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
476	            .trim();
477	    }
478	
479	    // ── Structured Parsers ─────────────────────────────────
480	
481	    /**
482	     * Parse equipment bonuses from an item's wiki page.
483	     * Tries: Infobox Bonuses, Infobox bonuses, Infobox Bonuses Beta
484	     */
485	    public async parseEquipmentBonuses(itemName: string): Promise<WikiEquipmentBonuses | null> {
486	        const wikitext = await this.getWikitextForName(itemName);
487	        if (!wikitext) return null;
488	
489	        const templateNames = ['Infobox Bonuses', 'Infobox bonuses', 'Infobox Bonuses Beta'];
490	        let bonuses: Record<string, string> | null = null;
491	
492	        for (const name of templateNames) {
493	            bonuses = this.extractTemplate(wikitext, name);
494	            if (bonuses) break;
495	        }
496	
497	        if (!bonuses) return null;
498	
499	        return {
500	            tier: this.safeInt(bonuses['tier'] || bonuses['level'] || '0'),
501	            slot: bonuses['slot'] || 'unknown',
502	            class: bonuses['class'] || bonuses['type'] || 'none',
503	            style: bonuses['style'] || bonuses['astyle'] || 'none',
504	            damage: this.safeInt(bonuses['damage'] || bonuses['dmg'] || '0'),
505	            accuracy: this.safeInt(bonuses['accuracy'] || bonuses['acc'] || '0'),
506	            armour: this.safeInt(bonuses['armour'] || bonuses['armor'] || bonuses['defence'] || '0'),
507	            lifeBonus: this.safeInt(bonuses['life'] || bonuses['lp'] || bonuses['lifepoints'] || '0'),
508	            prayerBonus: this.safeInt(bonuses['prayer'] || '0'),
509	            attackSpeed: bonuses['speed'] || bonuses['aspeed'] || 'average'
510	        };
511	    }
512	
513	    /**
514	     * Parse item metadata from an item's wiki page.
515	     */
516	    public async parseItemMeta(itemName: string): Promise<WikiItemMeta | null> {
517	        const wikitext = await this.getWikitextForName(itemName);
518	        if (!wikitext) return null;
519	
520	        const info = this.extractTemplate(wikitext, 'Infobox Item')
521	                   || this.extractTemplate(wikitext, 'Infobox item');
522	        if (!info) return null;
523	
524	        return {
525	            name: info['name'] || itemName,
526	            examine: info['examine'] || '',
527	            tradeable: this.safeBool(info['tradeable'] || info['tradable']),
528	            stackable: this.safeBool(info['stackable']),
529	            members: this.safeBool(info['members']),
530	            weight: parseFloat(info['weight'] || '0') || 0,
531	            highAlch: this.safeInt(info['high'] || info['highalch'] || '0'),
532	            lowAlch: this.safeInt(info['low'] || info['lowalch'] || '0'),
533	            // ge field: Grand Exchange mid-price (or ge_sell, exchange, value)
534	            geValue: this.safeInt(info['ge'] || info['exchange'] || info['ge_buy'] || info['value'] || '0'),
535	            quest: info['quest'] || 'No',
536	            release: info['release'] || 'Unknown'
537	        };
538	    }
539	
540	    /**
541	     * Parse monster metadata from an NPC's wiki page.
542	     */
543	    public async parseMonsterMeta(npcName: string): Promise<WikiMonsterMeta | null> {
544	        const wikitext = await this.getWikitextForName(npcName);
545	        if (!wikitext) return null;
546	
547	        const info = this.extractTemplate(wikitext, 'Infobox Monster')
548	                   || this.extractTemplate(wikitext, 'Infobox monster');
549	        if (!info) return null;
550	
551	        return {
552	            name: info['name'] || npcName,
553	            combatLevel: this.safeInt(info['combat'] || info['combatlevel'] || info['level'] || '0'),
554	            lifePoints: this.safeInt(info['lifepoints'] || info['lp'] || info['hp'] || '0'),
555	            maxHit: this.safeInt(info['max hit'] || info['maxhit'] || '0'),
556	            weakness: info['weakness'] || 'None',
557	            slayerLevel: this.safeInt(info['slaylvl'] || info['slayerlevel'] || '0'),
558	            slayerCategory: info['slayercat'] || info['category'] || 'None',
559	            aggressive: this.safeBool(info['aggressive']),
560	            poisonous: this.safeBool(info['poisonous'] || info['poison']),
561	            attackStyle: info['attack style'] || info['attackstyle'] || info['style'] || 'Melee',
562	            members: this.safeBool(info['members']),
563	            experience: this.safeInt(info['experience'] || info['xp'] || '0'),
564	            
565	            // March 2026 Combat Affinities
566	            defence: this.safeInt(info['defence'] || '0'),
567	            armour: this.safeInt(info['armour'] || '0'),
568	            affinityMelee: this.safeInt(info['aff_melee'] || '55'),
569	            affinityRanged: this.safeInt(info['aff_ranged'] || '55'),
570	            affinityMagic: this.safeInt(info['aff_magic'] || '55'),
571	            affinityNecromancy: this.safeInt(info['aff_necromancy'] || '55')
572	        };
573	    }
574	
575	    /**
576	     * Parse all drop table entries from a monster's wiki page.
577	     * Includes sub-table resolution (Rare drop table, Gem drop table, etc.)
578	     */
579	    public async parseDropTables(npcName: string): Promise<WikiDropTable[]> {
580	        const wikitext = await this.getWikitextForName(npcName);
581	        if (!wikitext) return [];
582	
583	        const tables: WikiDropTable[] = [];
584	
585	        // Extract all DropsLine instances from the page
586	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
587	
588	        if (dropLines.length > 0) {
589	            const mainEntries: WikiDropEntry[] = dropLines.map(dl => ({
590	                itemName: dl['name'] || dl['_1'] || 'Unknown',
591	                quantity: dl['quantity'] || dl['_2'] || '1',
592	                rarity: dl['rarity'] || dl['_3'] || 'Unknown',
593	                isMembers: this.safeBool(dl['members']),
594	                notes: dl['raritynotes'] || dl['altrarity'] || '',
595	                // ge: Some DropsLine templates include a |ge= param for price override
596	                geValue: this.safeInt(dl['ge'] || dl['value'] || dl['price'] || '0')
597	            }));
598	
599	            tables.push({
600	                section: 'Main',
601	                entries: mainEntries
602	            });
603	        }
604	
605	        // Detect and resolve sub-table references
606	        const subTableRefs = this.detectSubTableRefs(wikitext);
607	        for (const ref of subTableRefs) {
608	            logger.info({ ref, npc: npcName }, 'Resolving sub-table reference...');
609	            const subEntries = await this.resolveSubTable(ref);
610	            if (subEntries.length > 0) {
611	                tables.push({
612	                    section: ref,
613	                    entries: subEntries
614	                });
615	            }
616	        }
617	
618	        return tables;
619	    }
620	
621	    // ── Sub-Table Resolution ───────────────────────────────
622	
623	    /** Known sub-drop-table templates on RS Wiki. */
624	    private static readonly KNOWN_SUB_TABLES = [
625	        'Rare drop table',
626	        'Gem drop table',
627	        'Herb drop table',
628	        'Seed drop table',
629	        'Salvage drop table',
630	        'Triskelion drop table',
631	        'Ushabti drop table',
632	        'Shard drop table',
633	        'Spirit gem drop table',
634	        'Uncommon drop table',
635	        'Common drop table',
636	        'Charm drop table'
637	    ];
638	
639	    /**
640	     * Detect references to sub-drop-tables in the wikitext.
641	     */
642	    private detectSubTableRefs(wikitext: string): string[] {
643	        const found: string[] = [];
644	        const lowerText = wikitext.toLowerCase();
645	
646	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
647	            if (lowerText.includes(`{{${table.toLowerCase()}`)) {
648	                found.push(table);
649	            }
650	        }
651	
652	        return found;
653	    }
654	
655	    /**
656	     * Fetch and parse a sub-drop-table template page.
657	     * These live at Template:{name} on the wiki.
658	     */
659	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
660	        // Check cache
661	        const cached = this.readCache('templates', templateName);
662	        if (cached?.entries) {
663	            logger.debug({ templateName }, 'Sub-table served from cache.');
664	            return cached.entries;
665	        }
666	
667	        // Fetch the template page
668	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
669	        if (!wikitext) return [];
670	
671	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
672	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
673	            itemName: dl['name'] || dl['_1'] || 'Unknown',
674	            quantity: dl['quantity'] || dl['_2'] || '1',
675	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
676	            isMembers: this.safeBool(dl['members']),
677	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
678	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
679	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
680	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
681	        }));
682	
683	        // Cache the resolved sub-table
684	        this.writeCache('templates', templateName, { entries });
685	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
686	
687	        return entries;
688	    }
689	
690	    // ── High-Level API ─────────────────────────────────────
691	
692	    /**
693	     * Full enrichment pipeline for an equipment item.
694	     * Returns bonuses, item metadata, and all raw infobox variables.
695	     */
696	    public async enrichItem(name: string): Promise<WikiPageData> {
697	        const cached = this.readCache('items', name);
698	        if (cached && cached.title) {
699	            logger.debug({ name }, 'Item enrichment served from cache.');
700	            return cached;
701	        }
702	
703	        const bonuses = await this.parseEquipmentBonuses(name);
704	        const itemMeta = await this.parseItemMeta(name);
705	
706	        // Extract all raw variables from any infobox
707	        const wikitext = await this.getWikitextForName(name);
708	        const rawVariables = wikitext
709	            ? (this.extractTemplate(wikitext, 'Infobox Item')
710	               || this.extractTemplate(wikitext, 'Infobox Bonuses')
711	               || {})
712	            : {};
713	
714	        const result: WikiPageData = {
715	            title: name,
716	            fetchedAt: Date.now(),
717	            bonuses,
718	            itemMeta,
719	            monsterMeta: null,
720	            dropTables: [],
721	            rawVariables
722	        };
723	
724	        this.writeCache('items', name, result);
725	        return result;
726	    }
727	
728	    /**
729	     * Full enrichment pipeline for a monster/NPC.
730	     * Returns stats, drop tables (with sub-tables), and all raw infobox variables.
731	     */
732	    public async enrichMonster(name: string): Promise<WikiPageData> {
733	        const cached = this.readCache('monsters', name);
734	        if (cached && cached.title) {
735	            logger.debug({ name }, 'Monster enrichment served from cache.');
736	            return cached;
737	        }
738	
739	        const monsterMeta = await this.parseMonsterMeta(name);
740	        const dropTables = await this.parseDropTables(name);
741	
742	        const wikitext = await this.getWikitextForName(name);
743	        const rawVariables = wikitext
744	            ? (this.extractTemplate(wikitext, 'Infobox Monster') || {})
745	            : {};
746	
747	        const result: WikiPageData = {
748	            title: name,
749	            fetchedAt: Date.now(),
750	            bonuses: null,
751	            itemMeta: null,
752	            monsterMeta,
753	            dropTables,
754	            rawVariables
755	        };
756	
757	        this.writeCache('monsters', name, result);
758	        return result;
759	    }
760	
761	    /**
762	     * Batch enrichment with progress callback.
763	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
764	     */
765	    public async batchEnrich(
766	        names: string[],
767	        type: 'item' | 'monster',
768	        onProgress?: (current: number, total: number, name: string) => void
769	    ): Promise<Map<string, WikiPageData>> {
770	        const results = new Map<string, WikiPageData>();
771	
772	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
773	
774	        for (let i = 0; i < names.length; i++) {
775	            const name = names[i];
776	            onProgress?.(i + 1, names.length, name);
777	
778	            try {
779	                const data = type === 'item'
780	                    ? await this.enrichItem(name)
781	                    : await this.enrichMonster(name);
782	                results.set(name, data);
783	            } catch (err) {
784	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
785	            }
786	        }
787	
788	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
789	        return results;
790	    }
791	
792	    // ── Integration Helper ─────────────────────────────────
793	
794	    /**
795	     * Converts wiki bonuses into a patch compatible with ItemBook's semanticStats.
796	     * Use this to fill gaps in item_definitions_enriched.json.
797	     */
798	    public toItemBookPatch(bonuses: WikiEquipmentBonuses): Record<string, any> {
799	        const patch: Record<string, any> = {};
800	
801	        if (bonuses.tier > 0) {
802	            const cls = bonuses.class.toLowerCase();
803	            if (cls === 'melee' || bonuses.style === 'slash' || bonuses.style === 'stab' || bonuses.style === 'crush') {
804	                patch.req_attack = bonuses.tier;
805	            } else if (cls === 'ranged') {
806	                patch.req_ranged = bonuses.tier;
807	            } else if (cls === 'magic') {
808	                patch.req_magic = bonuses.tier;
809	            } else if (cls === 'necromancy') {
810	                patch.req_necromancy = bonuses.tier;
811	            }
812	            patch.tier = bonuses.tier;
813	        }
814	
815	        if (bonuses.damage > 0) patch.damage = bonuses.damage;
816	        if (bonuses.accuracy > 0) patch.accuracy = bonuses.accuracy;
817	        if (bonuses.armour > 0) patch.armour = bonuses.armour;
818	        if (bonuses.lifeBonus > 0) patch.lifeBonus = bonuses.lifeBonus;
819	        if (bonuses.prayerBonus > 0) patch.prayerBonus = bonuses.prayerBonus;
820	        patch.slot = bonuses.slot;
821	        patch.style = bonuses.style;
822	        patch.attackSpeed = bonuses.attackSpeed;
823	
824	        return patch;
825	    }
826	
827	    // ── Utilities ──────────────────────────────────────────
828	
829	    private safeInt(value: string): number {
830	        const cleaned = value.replace(/,/g, '').replace(/[^0-9.-]/g, '');
831	        const parsed = parseInt(cleaned, 10);
832	        return isNaN(parsed) ? 0 : parsed;
833	    }
834	
835	    private safeBool(value: string | undefined): boolean {
836	        if (!value) return false;
837	        const lower = value.toLowerCase().trim();
838	        return lower === 'yes' || lower === 'true' || lower === '1';
839	    }
840	
841	    /**
842	     * Session telemetry — how many API calls have been made.
843	     */
844	    public getStats(): { requestCount: number; lastRequest: number } {
845	        return {
846	            requestCount: this.requestCount,
847	            lastRequest: this.lastRequestTime
848	        };
849	    }
850	}
