127	    private serializeField(field: GhostSplatField, state?: GameState): any {
128	        return {
129	            tickDepth: field.tickDepth,
130	            heatmap: Array.from(field.heatmap),
131	            projections: Array.from(field.projections.entries()).map(([id, ghost]) => {
132	                // Enrich projections with cache-derived metrics
133	                let metrics: any = null;
134	                if (id.startsWith('npc_')) {
135	                    const npcId = parseInt(id.replace('npc_', ''), 10);
136	                    metrics = this.spatialRegistry.getMetrics(npcId);
137	                }
138	                return [id, {
139	                    ...ghost,
140	                    metrics: metrics ? {
141	                        radius: metrics.tileScale.radius,
142	                        height: metrics.tileScale.height,
143	                        volume: metrics.tileScale.volume
144	                    } : null
145	                }];
146	            }),
147	            gaussians: field.gaussians ? Array.from(field.gaussians) : null,
148	            safespots: field.safespots,
149	            center: (() => {
150	                if (!state) return { x: 0, y: 0, plane: 0 };
151	                const firstPlayer = state.players.values().next().value;
152	                return firstPlayer
153	                    ? { x: firstPlayer.x, y: firstPlayer.y, plane: firstPlayer.plane }
154	                    : { x: 0, y: 0, plane: 0 };
155	            })()
156	        };
157	    }
