171	    private projectNpcMovement(state: GameState, field: GhostSplatField): void {
172	        // Iterate the authoritative npcMap registry (always populated by SimulationHarness).
173	        // npcSpatialIndex is a secondary index that isn't reliably maintained.
174	        for (const [npcId, npc] of state.npcMap) {
175	            const source = (npc.path && npc.path.length > 0) ? 'path_queue'
176	                : (npc.interactionState === 'MOVING' && npc.metadata?.targetCoord) ? 'extrapolation'
177	                : 'offline_fallback';
178	            const projectedCoord = this.extrapolate(npc, field.tickDepth);
179	            
180	            const ghost: EntityGhost = {
181	                entityId: `npc_${npc.id}`,
182	                projectedCoord,
183	                ticksAhead: field.tickDepth,
184	                confidence: source === 'path_queue' ? 1.0 : source === 'extrapolation' ? 0.8 : 0.5,
185	                originType: 'rsmv',
186	                source
187	            };
188	            
189	            field.projections.set(ghost.entityId, ghost);
190	            
191	            // Log prediction
192	            const clock = CanonicalClock.getInstance();
193	            const currentTick = clock.simulatedNow();
194	            const metrics = this.spatialRegistry.getMetrics(npc.id);
195	            const contextStr = JSON.stringify({
196	                name: npc.name || `NPC ${npc.id}`,
197	                radius: metrics?.tileScale?.radius || 1,
198	                source: source,
199	                pathLength: npc.path?.length || 0,
200	                targetCoord: npc.metadata?.targetCoord,
201	                tickDepth: field.tickDepth
202	            });
203	            
204	            PredictionRegistry.getInstance().logSpatialPrediction({
205	                tick: currentTick + field.tickDepth,
206	                entityId: ghost.entityId,
207	                predictedCoord: projectedCoord,
208	                confidence: ghost.confidence,
209	                context: contextStr
210	            });
211	            
212	            // Splat the projection onto the heatmap
213	            if (projectedCoord) {
214	                // Map world coords to inner 64x64 grid (indices 1-64), padding at 0 and 65
215	                const INNER_SIZE = 64;
216	                const PADDING = 1;
217	
218	                // Euclidean modulo: handles negative world coords correctly
219	                const innerX = ((projectedCoord.x % INNER_SIZE) + INNER_SIZE) % INNER_SIZE;
220	                const innerY = ((projectedCoord.y % INNER_SIZE) + INNER_SIZE) % INNER_SIZE;
221	
222	                // Offset by padding to place in 1-64 range
223	                const localX = innerX + PADDING;
224	                const localY = innerY + PADDING;
225	
226	                // Only splat on inner tiles, never on sentinel padding
227	                if (localX >= PADDING && localX < PADDING + INNER_SIZE && 
228	                    localY >= PADDING && localY < PADDING + INNER_SIZE) {
229	                    const idx = localY * PADDED_SIZE + localX;
230	                    field.heatmap[idx] += 1; // Increase combined threat weight
231	                    if (field.entityHeat) field.entityHeat[idx] += 1; // Factional weighting
232	                }
233	            }
234	        }
235	    }
