237	    private projectPlayer(playerAgent: PlayerAgent | undefined, field: GhostSplatField): void {
238	        if (!playerAgent) return;
239	        
240	        const ghosts = playerAgent.projectSelf(field.tickDepth);
241	        for (const ghost of ghosts) {
242	            field.projections.set(ghost.entityId, ghost);
243	
244	            // Splat player's ghost onto the heatmap as self-awareness
245	            const localX = ghost.projectedCoord.x % PADDED_SIZE;
246	            const localY = ghost.projectedCoord.y % PADDED_SIZE;
247	            
248	            if (localX >= 0 && localX < PADDED_SIZE && localY >= 0 && localY < PADDED_SIZE) {
249	                const idx = localY * PADDED_SIZE + localX;
250	                field.heatmap[idx] += 1;
251	                if (field.avatarHeat) field.avatarHeat[idx] += 1; // Factional weighting
252	            }
253	        }
254	    }
