256	    private extrapolate(npc: NPC, ticksAhead: number): Coord {
257	        // High-Fidelity Projection: Consume actual A* path geometry if available
258	        if (npc.path && npc.path.length > 0) {
259	            const index = Math.min(ticksAhead - 1, npc.path.length - 1);
260	            if (index >= 0) {
261	                return npc.path[index];
262	            }
263	        }
264	
265	        // Visceral Fallback: Linear Extrapolation for dummy/legacy endpoints
266	        if (npc.interactionState === 'MOVING' && npc.metadata?.targetCoord) {
267	            return {
268	                x: npc.metadata.targetCoord.x,
269	                y: npc.metadata.targetCoord.y,
270	                plane: npc.metadata.targetCoord.plane ?? npc.coord.plane
271	            };
272	        }
273	        return npc.coord;
274	    }
