276	    private getThreatModulation(playerAgent?: PlayerAgent): ThreatModulation {
277	        const intent = playerAgent?.getCombatIntent() || 'aggressive';
278	        switch (intent) {
279	            case 'cowardly': return { intent, multiplier: 1.5, safespotWeight: 2.0, targetFocus: 0.3 };
280	            case 'aggressive': return { intent, multiplier: 0.7, safespotWeight: 0.5, targetFocus: 1.5 };
281	            case 'predator': return { intent, multiplier: 0.4, safespotWeight: 0.1, targetFocus: 2.0 };
282	            case 'methodical': return { intent, multiplier: 1.0, safespotWeight: 1.0, targetFocus: 1.0 };
283	            default: return { intent, multiplier: 1.0, safespotWeight: 1.0, targetFocus: 1.0 };
284	        }
285	    }
