287	    private calculateThreatHeatmap(field: GhostSplatField, state?: GameState, playerAgent?: PlayerAgent): void {
288	        const tempHeatmap = new Uint8Array(PADDED_SIZE * PADDED_SIZE);
289	        const mod = this.getThreatModulation(playerAgent);
290	        
291	        field.projections.forEach((ghost, entityId) => {
292	            if (entityId.startsWith('player_')) return;
293	
294	            const INNER_SIZE = 64;
295	            const PADDING = 1;
296	
297	            const innerX = ((ghost.projectedCoord.x % INNER_SIZE) + INNER_SIZE) % INNER_SIZE;
298	            const innerY = ((ghost.projectedCoord.y % INNER_SIZE) + INNER_SIZE) % INNER_SIZE;
299	            const localX = innerX + PADDING;
300	            const localY = innerY + PADDING;
301	            
302	            // ── Cache-Derived Attack Range ─────────────────────────────────────
303	            // Pull attack range from live NPC state (populated by CacheForensicsLimb
304	            // entity records). Falls back to 2 only when metadata is absent.
305	            let aggroRange = 2;
306	            if (state) {
307	                const npcIdStr = entityId.replace('npc_', '');
308	                const npcId = parseInt(npcIdStr, 10);
309	                if (!isNaN(npcId)) {
310	                    const npc = state.npcMap.get(npcId);
311	                    const cacheRange = (npc as any)?.combatStats?.attackRange;
312	                    if (typeof cacheRange === 'number' && cacheRange > 0) {
313	                        aggroRange = cacheRange;
314	                    } else {
315	                        logger.debug({ entityId }, '[GhostSplat] attackRange not in cache — using default 2');
316	                    }
317	                }
318	            }
319	
320	            // --- COGNITIVE ADAPTATION (Phase 45) ---
321	            try {
322	                const hexagram = HexagramManager.getInstance().getInterpretation();
323	                const variance = hexagram.aesthetics.thermalVariance || 0.5;
324	                // Scale base range by variance: variance 0.0 (Quiet) -> 1.0x, variance 1.0 (Agitated) -> 1.5x
325	                aggroRange = Math.max(1, Math.round(aggroRange * (1 + variance * 0.5)));
326	            } catch (e) {
327	                // Fallback to base aggroRange
328	            }
329	
330	            // Apply combat intent modulation
331	            aggroRange = Math.max(1, Math.round(aggroRange * mod.multiplier));
332	
333	            // Target focus check: ignore minor NPCs if focus is high
334	            const primaryTargetId = (playerAgent as any)?.avatar?.metadata?.currentTargetId;
335	            if (mod.targetFocus > 1.0 && primaryTargetId && entityId !== primaryTargetId && aggroRange > 2) {
336	                return; // Skip this NPC in heatmap
337	            }
338	
339	            for (let dx = -aggroRange; dx <= aggroRange; dx++) {
340	                for (let dy = -aggroRange; dy <= aggroRange; dy++) {
341	                    const nx = localX + dx;
342	                    const ny = localY + dy;
343	                    if (nx >= PADDING && nx < PADDING + INNER_SIZE && ny >= PADDING && ny < PADDING + INNER_SIZE) {
344	                        tempHeatmap[ny * PADDED_SIZE + nx] += 1;
345	                    }
346	                }
347	            }
348	        });
349	
350	        // Merge back into original heatmap.
351	        for (let i = 0; i < field.heatmap.length; i++) {
352	            field.heatmap[i] += tempHeatmap[i];
353	        }
354	    }
