356	    private identifySafespots(playerAgent: PlayerAgent | undefined, field: GhostSplatField): void {
357	        const startX = Math.floor(PADDED_SIZE / 2) - 10;
358	        const startY = Math.floor(PADDED_SIZE / 2) - 10;
359	
360	        for (let dx = 0; dx < 20; dx++) {
361	            for (let dy = 0; dy < 20; dy++) {
362	                const lx = startX + dx;
363	                const ly = startY + dy;
364	                if (lx >= 0 && lx < PADDED_SIZE && ly >= 0 && ly < PADDED_SIZE) {
365	                    const idx = ly * PADDED_SIZE + lx;
366	                    if (field.heatmap[idx] === 0 && playerAgent) {
367	                        // World translation:
368	                        // Find the rx, ry offset from player coord vs PADDED_SIZE origin
369	                        const playerGhost = playerAgent.projectOffline(); // Provides safe fallback
370	                        const worldX = playerGhost.projectedCoord.x + (lx - (Math.floor(PADDED_SIZE / 2)));
371	                        const worldY = playerGhost.projectedCoord.y + (ly - (Math.floor(PADDED_SIZE / 2)));
372	                        field.safespots.push({ x: worldX, y: worldY, plane: playerGhost.projectedCoord.plane });
373	                    }
374	                }
375	            }
376	        }
377	    }
