379	    private generateGaussianTensor(field: GhostSplatField): void {
380	        const entityCount = field.projections.size;
381	        const tileCount = PADDED_SIZE * PADDED_SIZE;
382	        const totalCount = entityCount + tileCount;
383	
384	        // ── Phase-Aware Compute Scaling ──
385	        // During DEGRADING, the kernel restricts resources. Scale gaussian
386	        // resolution by the phase multiplier to shed load gracefully.
387	        let effectiveCount = totalCount;
388	        let downscaleFactor = 1.0;
389	        try {
390	            const kernel = EpistemicTransitionKernel.getInstance();
391	            const multiplier = kernel.getPhaseGateMultiplier();
392	            downscaleFactor = multiplier;
393	            if (multiplier < 1.0) {
394	                effectiveCount = Math.max(1, Math.floor(totalCount * multiplier));
395	                if (effectiveCount < totalCount) {
396	                    logger.debug({ original: totalCount, effective: effectiveCount, phase: kernel.getCurrentPhase() },
397	                        'Gaussian tensor downscaled by kernel phase gate');
398	                }
399	            }
400	        } catch {
401	            // Kernel not yet initialized
402	        }
403	
404	        const tensor = new Float32Array(effectiveCount * 13);
405	        let offset = 0;
406	        let processed = 0;
407	
408	        // ── 1. NTX 66x66 Environment Splats (The Echo Buffer) ──
409	        // We only generate the background if we have enough compute budget
410	        if (effectiveCount > entityCount) {
411	            const center = this.getCenterCoord(field);
412	            const spatial = SpatialSovereigntyLimb.getInstance();
413	            const brain = NecromancerBrain.getInstance();
414	            
415	            const startX = center.x - Math.floor(PADDED_SIZE / 2);
416	            const startY = center.y - Math.floor(PADDED_SIZE / 2);
417	            const plane = center.plane;
418	
419	            // Extract NTXBuffer
420	            const ntxBuffer: NTXBuffer = new Array(PADDED_SIZE);
421	            const baseSH = new Float32Array([
422	                0.5, 0.5, 0.5, 
423	                0.5, 0.5, 0.5, 
424	                0.5, 0.5, 0.5
425	            ]);
426	
427	            for (let x = 0; x < PADDED_SIZE; x++) {
428	                ntxBuffer[x] = new Array(PADDED_SIZE);
429	                for (let y = 0; y < PADDED_SIZE; y++) {
430	                    const wx = startX + x;
431	                    const wy = startY + y;
432	                    const height = spatial.getAltitude(plane, wx, wy) / 32;
433	                    const flags = spatial.getLegacyMask(plane, wx, wy);
434	                    ntxBuffer[x][y] = {
435	                        mu: [wx, height, wy],
436	                        sigma: [[0.5, 0, 0], [0, 0.1, 0], [0, 0, 0.5]],
437	                        opacity: 1.0,
438	                        sh_coeffs: baseSH,
439	                        tile_flags: flags
440	                    };
441	                }
442	            }
443	
444	            // Apply predictive lighting (Spherical Harmonics)
445	            const litBuffer = brain.predictLighting(ntxBuffer, field.tickDepth);
446	
447	            // Serialize into tensor (skipping based on downscale to maintain spread)
448	            const skipStep = Math.max(1, Math.floor(1 / downscaleFactor));
449	            
450	            for (let x = 0; x < PADDED_SIZE; x += skipStep) {
451	                for (let y = 0; y < PADDED_SIZE; y += skipStep) {
452	                    if (processed >= effectiveCount - entityCount) break;
453	                    
454	                    const g = litBuffer[x][y];
455	                    if (!g) continue;
456	
457	                    // Position (relative to center)
458	                    tensor[offset + 0] = g.mu[0] - center.x;
459	                    tensor[offset + 1] = g.mu[1]; // height
460	                    tensor[offset + 2] = g.mu[2] - center.y;
461	
462	                    // Covariance (Diag approx)
463	                    tensor[offset + 3] = 0.5;
464	                    tensor[offset + 4] = 0;
465	                    tensor[offset + 5] = 0;
466	                    tensor[offset + 6] = 0.1;
467	                    tensor[offset + 7] = 0;
468	                    tensor[offset + 8] = 0.5;
469	
470	                    // Color (extract SH degree 0)
471	                    tensor[offset + 9]  = g.sh_coeffs[0];
472	                    tensor[offset + 10] = g.sh_coeffs[1];
473	                    tensor[offset + 11] = g.sh_coeffs[2];
474	
475	                    // Opacity
476	                    tensor[offset + 12] = g.opacity;
477	
478	                    offset += 13;
479	                    processed++;
480	                }
481	            }
482	        }
483	
484	        // ── 2. Dynamic Entity Splats ──
485	        field.projections.forEach((ghost, id) => {
486	            if (processed >= effectiveCount) return;
487	            processed++;
488	
489	            // 1. Position (Relative to local 66x66 center)
490	            const center = this.getCenterCoord(field);
491	            const lx = ghost.projectedCoord.x - center.x;
492	            const ly = ghost.projectedCoord.y - center.y;
493	            const lz = (ghost.projectedCoord.plane || 0) * 2; // Vertical separation
494	
495	            tensor[offset + 0] = lx;
496	            tensor[offset + 1] = lz; // Y-up convention for many renderers
497	            tensor[offset + 2] = ly;
498	
499	            // 2. Covariance (Approximated as a sphere/ellipsoid)
500	            // [s11, s12, s13, s22, s23, s33]
501	            const isNpc = id.startsWith('npc_');
502	            let scale = isNpc ? 0.8 : 0.5; // Fallback default
503	
504	            if (isNpc) {
505	                const npcId = parseInt(id.replace('npc_', ''), 10);
506	                if (!isNaN(npcId)) {
507	                    const metrics = this.spatialRegistry.getMetrics(npcId);
508	                    if (metrics) {
509	                        // Cache-derived physical presence shapes the Gaussian
510	                        scale = metrics.tileScale.radius;
511	                        
512	                        // Optional: Shape the ellipsoid based on actual proportions
513	                        // If height > radius*2, stretch vertically (flying/crawling entities)
514	                        const heightScale = metrics.tileScale.height / (metrics.tileScale.radius * 2);
515	                        if (heightScale > 1.5) {
516	                            // Tall entity — stretch Y (s33 in Y-up convention)
517	                            tensor[offset + 8] = scale * Math.min(heightScale, 3.0); // Cap at 3x
518	                        }
519	                    }
520	                }
521	            }
522	
523	            tensor[offset + 3] = scale; // s11 (X)
524	            tensor[offset + 4] = 0;     // s12
525	            tensor[offset + 5] = 0;     // s13
526	            tensor[offset + 6] = scale; // s22 (Z, horizontal)
527	            tensor[offset + 7] = 0;     // s23
528	            tensor[offset + 8] = isNpc && tensor[offset + 8] > scale ? tensor[offset + 8] : scale; // s33 (Y, vertical)
529	
530	            // 3. Color (SH Level 0 - RGB)
531	            if (isNpc) {
532	                // Threat color: Orange to Red
533	                tensor[offset + 9] = 1.0;  // R
534	                tensor[offset + 10] = 0.4; // G
535	                tensor[offset + 11] = 0.0; // B
536	            } else {
537	                // Player color: Cyan
538	                tensor[offset + 9] = 0.0;  // R
539	                tensor[offset + 10] = 1.0; // G
540	                tensor[offset + 11] = 1.0; // B
541	            }
542	
543	            // 4. Opacity
544	            tensor[offset + 12] = ghost.confidence;
545	
546	            offset += 13;
547	        });
548	
549	        field.gaussians = tensor;
550	    }
