552	    private getCenterCoord(field: GhostSplatField): Coord {
553	        const playerGhost = field.projections.get('player_sovereign');
554	        if (playerGhost) return playerGhost.projectedCoord;
555	        
556	        // Fallback if no player
557	        if (field.projections.size > 0) {
558	            const firstProjection = field.projections.values().next().value;
559	            if (firstProjection) {
560	                return firstProjection.projectedCoord;
561	            }
562	        }
563	        return { x: 3200, y: 3200, plane: 0 };
564	    }
