/**
 * Core type definitions for pog2-sovereign.
 * Aggregator and Domain-Specific Taxonomy.
 */

import { createRequire } from 'module';
const require = createRequire(import.meta.url);
import { join, basename } from 'path';
// HealthReport and ServiceHealthState defined below to resolve broken import
import { SovereignDomain } from '../types/SovereignDomain.js';

export { SovereignDomain };
export type Direction = 'north' | 'south' | 'east' | 'west' | 'north-east' | 'north-west' | 'south-east' | 'south-west' | 'up' | 'down';

export enum LogicalSignature {
    CONSUMABLE_ROLL = 'CONSUMABLE_ROLL',
    LOOT_TABLE_ROLL = 'LOOT_TABLE_ROLL',
    TRANSPORT_ACTUATOR = 'TRANSPORT_ACTUATOR',
    TELEPORT_ACTUATOR = 'TELEPORT_ACTUATOR',
    BANK_DEPOSIT_ACTUATOR = 'BANK_DEPOSIT_ACTUATOR',
    PRACTICE_SKILL_NODE = 'PRACTICE_SKILL_NODE',
    CONSUMABLE_SKILL_STATION = 'CONSUMABLE_SKILL_STATION',
    SPATIAL_SHIFT = 'SPATIAL_SHIFT',
    ENTITY_MANIFEST = 'ENTITY_MANIFEST',
    PRIVILEGE_ELEVATION = 'PRIVILEGE_ELEVATION',
    NPC_DIALOGUE = 'NPC_DIALOGUE'
}
export enum SubstrateState {
    ONLINE = 'ONLINE',          // Full actuation and vision OK
    DEGRADED = 'DEGRADED',      // Vision OK, but actuation (rsmv write) blocked
    DEGRADED_IO = 'DEGRADED_IO', // I/O latency exceeding pulse budget
    OFFLINE = 'OFFLINE'         // Full substrate reachability failure (abort tick)
}

export interface SubstrateDeficit {
    type: 'NPC' | 'ITEM' | 'OBJECT' | 'TILE';
    id: number | string;
    requestedAtTick: number;
    reason: string;
}


export interface Coord {
    x: number;
    y: number;
    plane: number;
}

export interface RoutingDecision {
    model: string;
    metadata: {
        source: string;
        latencyMs: number;
        reasoning: string;
        path?: number[];
        error?: string;
    };
}

export interface RoutingContext {
    prompt: string;
    weightedTasks?: Record<string, number>;
    extension?: string;
    fileSize?: number;
    complexity?: CognitiveChoice;
    availableModels?: FreeModelConfig[];
    architectureAlignment?: string[];
    goldenTemplates?: string[];
    historicalPerformance?: ModelPerformance[];
    lessons?: Lesson[];
    metadata?: {
        ternarySignals?: {
            localAvailability: YaoState;
            historySignal: YaoState;
            supervisorSignal: YaoState;
            architectureAlignmentState: YaoState;
        };
        decisionDirective?: string;
        [key: string]: unknown;
    };
    hexagram?: any;
}

export interface RoutingStrategy {
    readonly name: string;
    route(context: RoutingContext): Promise<RoutingDecision | null>;
}

export interface TerminalStrategy extends RoutingStrategy {
    route(context: RoutingContext): Promise<RoutingDecision>;
}

export type ServiceHealthState = 'READY' | 'DEGRADED' | 'CRITICAL_FAILURE' | 'OFFLINE';

export type TodoStatus = 'pending' | 'in_progress' | 'completed' | 'cancelled';

export interface VarbitSnapshot {
    [id: number]: number;
}

export interface CompositeCondition {
    type: 'composite_and' | 'composite_or';
    conditions: string[];
}

export interface DirectionalCollision {
    // Walkable directions (true = can walk, false = blocked)
    north: boolean;
    south: boolean;
    east: boolean;
    west: boolean;

    // NPC-specific constraints (directions that only block NPCs, not players)
    npc_only_blocks?: Direction[];

    // Explicit blocked flags for API clarity (Derived: !north)
    northBlocked?: boolean;
    southBlocked?: boolean;
    eastBlocked?: boolean;
    westBlocked?: boolean;
}

export interface TileCollision {
    static: DirectionalCollision;
    dynamic: DirectionalCollision;
}

export interface SpatialSideEffect {
    type: 'dynamic_collision' | 'walkability_override' | 'special_property';
    mask?: number;           // 0x100, 0x2, etc.
    condition?: string;      // "is_active_follower == true"
    blocks_movement?: boolean;
    description?: string;
}

export interface CombatantState {
    adrenaline?: number; // 0 - 10000 (0.00% to 100.00%)
    necrosisStacks?: number;
    residualSouls?: number;
    bloodlustStacks?: number;           // New: Melee stack system (0-8)
    animaCharged?: boolean;             // New: Magic empower buff
    searingWindsTicksRemaining?: number; // New: Ranged buff duration
    shadowImbuedTicksRemaining?: number; // New: Ranged adrenaline buff duration

    // Necromancy Specifics
    conjureActive?: { skeleton: boolean, zombie: boolean, ghost: boolean, phantom: boolean };
    ritualState?: { soulsCaptured: number, corruptionLevel: number };
    stunCharges?: Record<string, number>; // New: Charge-based stun tracking (abilityId -> count)
    stunEndTick?: number;                 // New: Absolute tick when stun expires
    hp?: number;                        // Current HP for survival heuristics
    maxHp?: number;                     // Max HP for survival heuristics
    lastCombatTick: number; // Track for rhythm enforcement (e.g. 4-tick)
    cooldowns: Record<string, number>; // abilityId -> tickAvailable
    messages?: string[];                // Chat buffer for forensic triggers
}

export interface SovereignIntent {
    action: string;
    targetId: number | string;
    tickStarted: number;
    contextHash: string;
    coord?: Coord;
    abilityId?: string;
    range?: number;
}

export interface NPC extends CombatantState {
    id: number;
    npcId?: number;           // Cache definition ID (Major 18 archiveId)
    name: string;
    coord: Coord;
    x: number;
    y: number;
    plane: number;
    adrenaline?: number;
    adrenalinePercent?: number | string; // Support for formatted strings ("9.00%")
    necrosisStacks?: number;
    isFollower?: boolean;
    path?: Coord[];
    target?: number | Coord; // Entity ID or Destination
    interactionState: 'IDLE' | 'MOVING' | 'READY' | 'EXECUTING' | 'COOLDOWN';
    intent?: SovereignIntent;
    lastActionTick: number;
    currentHp?: number;       // Live HP tracker for combat evaluation
    combatStats?: {           // Optional combat metadata block
        currentHp: number;
        maxHp: number;
        attackLevel?: number;
        defenceLevel?: number;
    };

    brain?: {
        think: (tick: number, state: GameState, avatar: any) => void;
    };

    metadata?: Record<string, any>;
}

export interface GameObject {
    id: number;
    name: string;
    x: number;
    y: number;
    plane: number;
    metadata?: Record<string, any>;
}

export interface Item {
    id: number;
    amount: number;
    metadata?: Record<string, any>;
}

export interface Wallet {
    [currencyId: number]: number; // Map currency ID to amount
}

export enum EquipmentSlot {
    HEAD = 'head',
    CAPE = 'cape',
    NECK = 'neck',
    WEAPON = 'weapon',
    BODY = 'body',
    SHIELD = 'shield',
    LEGS = 'legs',
    HANDS = 'hands',
    FEET = 'feet',
    RING = 'ring',
    AMMO = 'ammo',
    AURA = 'aura',
    POCKET = 'pocket'
}

export interface Equipment {
    [slot: string]: Item | null;
}

export enum SkillId {
    ATTACK = 1,
    STRENGTH = 2,
    RANGED = 3,
    MAGIC = 4,
    DEFENCE = 5,
    CONSTITUTION = 6,
    PRAYER = 7,
    AGILITY = 8,
    HERBLORE = 9,
    THIEVING = 10,
    CRAFTING = 11,
    RUNECRAFTING = 12,
    MINING = 13,
    SMITHING = 14,
    FISHING = 15,
    COOKING = 16,
    FIREMAKING = 17,
    WOODCUTTING = 18,
    FLETCHING = 19,
    SLAYER = 20,
    FARMING = 21,
    CONSTRUCTION = 22,
    HUNTER = 23,
    SUMMONING = 24,
    DUNGEONEERING = 25,
    DIVINATION = 26,
    INVENTION = 27,
    ARCHAEOLOGY = 28,
    NECROMANCY = 29,
    TAMING = 30, // Speculative: 30th Skill Reservation
    QUEST_POINT = 31
}

export interface Skill {
    id: number;
    name: string;
    level: number;
    xp: number;
    virtualLevel?: number;
}

export interface Quest {
    id: number;
    name: string;
    status: 'NOT_STARTED' | 'IN_PROGRESS' | 'COMPLETED';
    points: number;
}

export interface QuestState {
    points: number;
    completedCount: number;
    quests: Record<number, Quest>;
}

export interface SovereignAvatar extends NPC {
    username: string;
    inventory: (Item | null)[]; // Fixed 28 slots
    bank: Item[];
    wallet: Wallet;
    equipment: Equipment;
    skills: Record<number, Skill>; // Map SkillId to Skill
    quests: QuestState;
    achievements: {
        points: number;
        completed: Record<string, boolean>;
    };
    metadata?: any;

    // Injectable State (Phase 15 Ignition)
    injectState(stateString: string): void;
    serializeState(): string;

    // Operational Limb Logic (Phase 13 NXT-grade)
    isDead: boolean;
    processTick(): void;
    isBusy(): boolean;
    lock(ticks: number): void;
    lockTicks: number; // Residual ticks until lock expires
    addItem(item: Item): boolean;
    removeItem(slot: number): Item | null;
    authenticDie(): Item[];
    respawn(): void;
    setEquipmentSlot(slot: EquipmentSlot, item: Item | null): void;
    pendingInteraction: { action: string; targetId: string } | null;

    // Adrenaline / Combat logic
    adrenalinePercent: string;
    addAdrenaline(amount: number): void;
    consumeAdrenaline(amount: number): boolean;
    state: GameState;
    currentPath: Coord[] | null;
    applyDamage(amount: number): void;
    heal(amount: number): void;
    plotPath?(
        targetX: number,
        targetY: number,
        pathfinder: any,
        context: any,
        collisionMatrix?: Map<string, any>
    ): boolean;
    firstEmptySlot(): number | null;
    appearanceEra?: 'pre_avatar' | 'transitional' | 'post_avatar';
    appearance?: {
        legacyAppearanceId?: number;
        bodyColors?: [number, number][];
        gender?: 'male' | 'female' | 'classic';
        composition?: {
            baseBodyId: number;
            gender: 'male' | 'female';
            skinTone: number;
            hairStyle: number;
            facialHair?: number;
            equipment: {
                head: number | null;
                cape: number | null;
                neck: number | null;
                weapon: number | null;
                body: number | null;
                shield: number | null;
                legs: number | null;
                hands: number | null;
                feet: number | null;
                ring: number | null;
                ammo: number | null;
            };
            chatheadId: number;
        };
    };
    // Note: interactionState, intent, and lastActionTick are inherited from NPC
}



export interface GroundItem {
    id: number;
    itemName?: string;
    rarityLabel?: string;
    /** Grand Exchange price in coins. 0 = unknown/untradeable. Used by LootBeamRegistry tier resolution. */
    geValue?: number;
    amount: number;
    x: number;
    y: number;
    plane: number;
    owner?: string;
    spawnTick: number;
}

export interface GraveMarker {
    id: string;
    items: Item[];
    x: number;
    y: number;
    plane: number;
    owner: string;
    creationTick: number;
    expiryTick: number;
}

export type EventSource = "ADMIN" | "SYSTEM" | "AI" | "WORLD_SCRIPT";

export type EventOutcome =
    | "SUCCESS"
    | "REJECTED_COLLISION"
    | "REJECTED_AUTHORITY"
    | "DEFERRED";

export type SignalSource = "SPATIAL" | "POLICY" | "DOMAIN" | "INFRASTRUCTURE" | "EXTERNAL";

export enum TruthClass {
    EXECUTION = 'EXECUTION',           // Raw substrate events (The "What Happened")
    CAUSAL = 'CAUSAL',                 // Hash-chained records (The "Provable History")
    INTERPRETATION = 'INTERPRETATION', // Derived patterns/pedagogy (The "What it Means")
    POLICY = 'POLICY',                 // Active gating/ISA rules (The "What is Allowed")
    ANOMALY = 'ANOMALY',               // Deviations/Shadow captures (The "What is Broken")
    INVARIANT = 'INVARIANT',           // Hardened structural laws (The "What is Constant")
    POLICY_DENIED = 'POLICY_DENIED'     // Gated by EpistemicValidator/ISA
}

/**
 * Epistemic Invariants - The "Physics of Truth" for POG2.
 * Hard-coded constraints that prevent semantic contamination across layers.
 */
export const EPISTEMIC_INVARIANTS = {
    LEDGER_CAUSALLY_CLOSED: true,    // Nothing can mutate past ledger records.
    INTERPRETATION_READ_ONLY: true,  // Interpretation cannot mutate Execution Truth.
    GOVERNANCE_OBSERVATIONAL: true,  // Governance must be derived from Truth, not vice-versa.
    ANOMALY_IMMUTABLE: true          // Anomalies cannot be reclassified as Truth without a replay.
} as const;

/**
 * TruthLattice - Formal precedence model for reconciliation.
 * Precedence: EXECUTION > INVARIANT > INTERPRETATION > ANOMALY
 */
export const TRUTH_PRECEDENCE: readonly TruthClass[] = [
    TruthClass.EXECUTION,
    TruthClass.CAUSAL,
    TruthClass.INVARIANT,
    TruthClass.POLICY,
    TruthClass.INTERPRETATION,
    TruthClass.ANOMALY
] as const;

export interface CausalEvidence {
    readonly source: SignalSource;
    readonly code: string;
    readonly description: string;
    readonly severity: "INFO" | "WARNING" | "BLOCKER";
    readonly metadata?: Record<string, any>;
}

export interface CausalTrace {
    readonly eventId: string;
    readonly tick: number;
    readonly signals: readonly CausalEvidence[];
    readonly resolvedOutcome: EventOutcome;
    readonly resolutionPointIndex?: number;
}

export interface LearningTrace {
    readonly eventId: string;
    readonly summary: string;
    readonly causalChain: readonly string[];
    readonly primaryDrivers: readonly string[];
}

export interface CausalPattern {
    readonly id: string;
    readonly label: string;
    readonly archetype: string;
    readonly frequency: number;
    readonly lastOccurredTick: number;
    readonly heuristic: string;
    readonly contributingSignals: readonly string[];
    readonly truthClass: TruthClass;
}

export interface PatternMemory {
    activePatterns: Map<string, CausalPattern>;
    totalTracesAnalyzed: number;
}

export interface InvariantRule {
    readonly id: string;
    readonly domain: string;
    readonly constraint: string;
    readonly validationPath: readonly string[];
    readonly confidence: number;
    readonly isTransferable: boolean;
    readonly truthClass: TruthClass;
}

export interface InvariantManifest {
    rules: InvariantRule[];
    lastCompiledTick: number;
}

export enum LearningFidelity {
    RAW = 0,
    CAUSAL = 1,
    PATTERN = 2,
    INVARIANT = 3,
    PEDAGOGY = 4
