247	    private detectEnergyFlow(field: GhostSplatField): 'ASCENDING' | 'DESCENDING' | 'STABLE' {
248	        const centerHeat = this.sampleRegion(field.heatmap, 28, 28, 38, 38);
249	        const peripheryHeat = this.sampleRegion(field.heatmap, 0, 0, 66, 66) - centerHeat;
250	        const centerAvg = centerHeat / 100;
251	        const peripheryAvg = peripheryHeat / (66 * 66 - 100);
252	        if (peripheryAvg > centerAvg * 1.3) return 'ASCENDING';
253	        if (centerAvg > peripheryAvg * 1.3) return 'DESCENDING';
254	        return 'STABLE';
255	    }
