516	            style: bonuses['style'] || bonuses['astyle'] || 'none',
517	            damage: this.safeInt(bonuses['damage'] || bonuses['dmg'] || '0'),
518	            accuracy: this.safeInt(bonuses['accuracy'] || bonuses['acc'] || '0'),
519	            armour: this.safeInt(bonuses['armour'] || bonuses['armor'] || bonuses['defence'] || '0'),
520	            lifeBonus: this.safeInt(bonuses['life'] || bonuses['lp'] || bonuses['lifepoints'] || '0'),
521	            prayerBonus: this.safeInt(bonuses['prayer'] || '0'),
522	            attackSpeed: bonuses['speed'] || bonuses['aspeed'] || 'average'
523	        };
524	    }
525	
526	    /**
527	     * Parse item metadata from an item's wiki page.
528	     */
529	    public async parseItemMeta(itemName: string): Promise<WikiItemMeta | null> {
530	        const wikitext = await this.getWikitextForName(itemName);
531	        if (!wikitext) return null;
532	
533	        const info = this.extractTemplate(wikitext, 'Infobox Item')
534	                   || this.extractTemplate(wikitext, 'Infobox item');
535	        if (!info) return null;
536	
537	        return {
538	            name: info['name'] || itemName,
539	            examine: info['examine'] || '',
540	            tradeable: this.safeBool(info['tradeable'] || info['tradable']),
541	            stackable: this.safeBool(info['stackable']),
542	            members: this.safeBool(info['members']),
543	            weight: parseFloat(info['weight'] || '0') || 0,
544	            highAlch: this.safeInt(info['high'] || info['highalch'] || '0'),
545	            lowAlch: this.safeInt(info['low'] || info['lowalch'] || '0'),
546	            // ge field: Grand Exchange mid-price (or ge_sell, exchange, value)
547	            geValue: this.safeInt(info['ge'] || info['exchange'] || info['ge_buy'] || info['value'] || '0'),
548	            quest: info['quest'] || 'No',
549	            release: info['release'] || 'Unknown'
550	        };
551	    }
552	
553	    /**
554	     * Parse monster metadata from an NPC's wiki page.
555	     */
556	    public async parseMonsterMeta(npcName: string): Promise<WikiMonsterMeta | null> {
557	        const wikitext = await this.getWikitextForName(npcName);
558	        if (!wikitext) return null;
559	
560	        const info = this.extractTemplate(wikitext, 'Infobox Monster')
561	                   || this.extractTemplate(wikitext, 'Infobox monster');
562	        if (!info) return null;
563	
564	        return {
565	            name: info['name'] || npcName,
566	            combatLevel: this.safeInt(info['combat'] || info['combatlevel'] || info['level'] || '0'),
567	            lifePoints: this.safeInt(info['lifepoints'] || info['lp'] || info['hp'] || '0'),
568	            maxHit: this.safeInt(info['max hit'] || info['maxhit'] || '0'),
569	            weakness: info['weakness'] || 'None',
570	            slayerLevel: this.safeInt(info['slaylvl'] || info['slayerlevel'] || '0'),
571	            slayerCategory: info['slayercat'] || info['category'] || 'None',
572	            aggressive: this.safeBool(info['aggressive']),
573	            poisonous: this.safeBool(info['poisonous'] || info['poison']),
574	            attackStyle: info['attack style'] || info['attackstyle'] || info['style'] || 'Melee',
575	            members: this.safeBool(info['members']),
576	            experience: this.safeInt(info['experience'] || info['xp'] || '0'),
577	            
578	            // March 2026 Combat Affinities
579	            defence: this.safeInt(info['defence'] || '0'),
580	            armour: this.safeInt(info['armour'] || '0'),
581	            affinityMelee: this.safeInt(info['aff_melee'] || '55'),
582	            affinityRanged: this.safeInt(info['aff_ranged'] || '55'),
583	            affinityMagic: this.safeInt(info['aff_magic'] || '55'),
584	            affinityNecromancy: this.safeInt(info['aff_necromancy'] || '55')
585	        };
586	    }
587	
588	    /**
589	     * Parse all drop table entries from a monster's wiki page.
590	     * Includes sub-table resolution (Rare drop table, Gem drop table, etc.)
591	     */
592	    public async parseDropTables(npcName: string): Promise<WikiDropTable[]> {
593	        const wikitext = await this.getWikitextForName(npcName);
594	        if (!wikitext) return [];
595	
596	        const tables: WikiDropTable[] = [];
597	
598	        // Extract all DropsLine instances from the page
599	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
600	
601	        if (dropLines.length > 0) {
602	            const mainEntries: WikiDropEntry[] = dropLines.map(dl => ({
603	                itemName: dl['name'] || dl['_1'] || 'Unknown',
604	                quantity: dl['quantity'] || dl['_2'] || '1',
605	                rarity: dl['rarity'] || dl['_3'] || 'Unknown',
606	                isMembers: this.safeBool(dl['members']),
607	                notes: dl['raritynotes'] || dl['altrarity'] || '',
608	                // ge: Some DropsLine templates include a |ge= param for price override
609	                geValue: this.safeInt(dl['ge'] || dl['value'] || dl['price'] || '0')
610	            }));
611	
612	            tables.push({
613	                section: 'Main',
614	                entries: mainEntries
615	            });
616	        }
617	
618	        // Detect and resolve sub-table references
619	        const subTableRefs = this.detectSubTableRefs(wikitext);
620	        for (const ref of subTableRefs) {
621	            logger.info({ ref, npc: npcName }, 'Resolving sub-table reference...');
622	            const subEntries = await this.resolveSubTable(ref);
623	            if (subEntries.length > 0) {
624	                tables.push({
625	                    section: ref,
626	                    entries: subEntries
627	                });
628	            }
629	        }
630	
631	        return tables;
632	    }
633	
634	    // ── Sub-Table Resolution ───────────────────────────────
635	
636	    /** Known sub-drop-table templates on RS Wiki. */
637	    private static readonly KNOWN_SUB_TABLES = [
638	        'Rare drop table',
639	        'Gem drop table',
640	        'Herb drop table',
641	        'Seed drop table',
642	        'Salvage drop table',
643	        'Triskelion drop table',
644	        'Ushabti drop table',
645	        'Shard drop table',
646	        'Spirit gem drop table',
647	        'Uncommon drop table',
648	        'Common drop table',
649	        'Charm drop table'
650	    ];
651	
652	    /**
653	     * Detect references to sub-drop-tables in the wikitext.
654	     */
655	    private detectSubTableRefs(wikitext: string): string[] {
656	        const found: string[] = [];
657	        const lowerText = wikitext.toLowerCase();
658	
659	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
660	            if (lowerText.includes(`{{${table.toLowerCase()}`)) {
661	                found.push(table);
662	            }
663	        }
664	
665	        return found;
666	    }
667	
668	    /**
669	     * Fetch and parse a sub-drop-table template page.
670	     * These live at Template:{name} on the wiki.
671	     */
672	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
673	        // Check cache
674	        const cached = this.readCache('templates', templateName);
675	        if (cached?.entries) {
676	            logger.debug({ templateName }, 'Sub-table served from cache.');
677	            return cached.entries;
678	        }
679	
680	        // Fetch the template page
681	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
682	        if (!wikitext) return [];
683	
684	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
685	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
686	            itemName: dl['name'] || dl['_1'] || 'Unknown',
687	            quantity: dl['quantity'] || dl['_2'] || '1',
688	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
689	            isMembers: this.safeBool(dl['members']),
690	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
691	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
692	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
693	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
694	        }));
695	
696	        // Cache the resolved sub-table
697	        this.writeCache('templates', templateName, { entries });
698	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
699	
700	        return entries;
701	    }
702	
703	    // ── Generic Enrichment Logic ─────────────────────────────
704	
705	    private detectPageType(wikitext: string): 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore' {
706	        const lower = wikitext.toLowerCase();
707	        if (lower.includes('{{infobox monster')) return 'npc';
708	        if (lower.includes('{{infobox item')) return 'item';
709	        if (lower.includes('{{infobox bonuses')) return 'equipment';
710	        if (lower.includes('{{infobox location')) || lower.includes('{{infobox area')) return 'place';
711	        if (lower.includes('{{infobox mechanic')) || lower.includes('{{infobox gameplay')) return 'mechanic';
712	        return 'lore';
713	    }
714	
715	    private async fetchCategoryMembers(pageTitle: string): Promise<string[]> {
716	        await this.throttle();
717	        const params = new URLSearchParams({
718	            action: 'query',
719	            format: 'json',
720	            list: 'categorymembers',
721	            cmtitle: pageTitle,
722	            cmlimit: '500',
723	            origin: '*'
724	        });
725	
726	        try {
727	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
728	                headers: { 'User-Agent': this.USER_AGENT },
729	                signal: AbortSignal.timeout(10000)
730	            });
731	            const data = await response.json() as any;
732	            return data.query?.categorymembers?.map((m: any) => m.title) || [];
733	        } catch (err) {
734	            logger.error({ pageTitle, err }, 'Failed to fetch category members.');
735	            return [];
736	        }
737	    }
738	
739	    private async fetchExtract(pageTitle: string): Promise<string | null> {
740	        await this.throttle();
741	        const params = new URLSearchParams({
742	            action: 'query',
743	            format: 'json',
744	            prop: 'extracts',
745	            exintro: '1',
746	            explaindepth: '0',
747	            titles: pageTitle,
748	            origin: '*'
749	        });
750	
751	        try {
752	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
753	                headers: { 'User-Agent': this.USER_AGENT },
754	                signal: AbortSignal.timeout(10000)
755	            });
756	            const data = await response.json() as any;
757	            const pages = data.query?.pages;
758	            if (!pages) return null;
759	            const pageId = Object.keys(pages)[0];
760	            return pages[pageId]?.extract || null;
761	        } catch (err) {
762	            logger.error({ pageTitle, err }, 'Failed to fetch page extract.');
763	            return null;
764	        }
765	    }
766	
767	    public async enrichGeneric(pageTitle: string): Promise<WikiPageData | null> {
768	        const cached = this.readCache('generic', pageTitle);
769	        if (cached && cached.title) {
770	            logger.debug({ pageTitle }, 'Generic enrichment served from cache.');
771	            return cached;
772	        }
773	
774	        const wikitext = await this.getWikitextForName(pageTitle);
775	        if (!wikitext) return null;
776	
777	        const pageType = this.detectPageType(wikitext);
778	        let categoryMembers: string[] | undefined;
779	        if (pageTitle.startsWith('Category:')) {
780	            categoryMembers = await this.fetchCategoryMembers(pageTitle);
781	        }
782	
783	        const result: WikiPageData = {
784	            title: pageTitle,
785	            fetchedAt: Date.now(),
786	            bonuses: null,
787	            itemMeta: null,
788	            monsterMeta: null,
789	            dropTables: [],
790	            rawVariables: this.extractTemplate(wikitext, 'Infobox Item')
791	                         || this.extractTemplate(wikitext, 'Infobox Monster')
792	                         || this.extractTemplate(wikitext, 'Infobox Bonuses')
793	                         || {},
794	            pageType,
795	            extract: await this.fetchExtract(pageTitle),
796	            categoryMembers
797	        };
798	
799	        this.writeCache('generic', pageTitle, result);
800	        return result;
801	    }
802	
803	    // ── High-Level API ─────────────────────────────────────
804	
805	    /**
806	     * Full enrichment pipeline for an equipment item.
807	     * Returns bonuses, item metadata, and all raw infobox variables.
808	     */
809	    public async enrichItem(name: string): Promise<WikiPageData> {
810	        const cached = this.readCache('items', name);
811	        if (cached && cached.title) {
812	            logger.debug({ name }, 'Item enrichment served from cache.');
813	            return cached;
814	        }
815	
816	        const bonuses = await this.parseEquipmentBonuses(name);
817	        const itemMeta = await this.parseItemMeta(name);
818	
819	        // Extract all raw variables from any infobox
820	        const wikitext = await this.getWikitextForName(name);
821	        const rawVariables = wikitext
822	            ? (this.extractTemplate(wikitext, 'Infobox Item')
823	               || this.extractTemplate(wikitext, 'Infobox Bonuses')
824	               || {})
825	            : {};
826	
827	        const result: WikiPageData = {
828	            title: name,
829	            fetchedAt: Date.now(),
830	            bonuses,
831	            itemMeta,
832	            monsterMeta: null,
833	            dropTables: [],
834	            rawVariables
835	        };
836	
837	        this.writeCache('items', name, result);
838	        return result;
839	    }
840	
841	    /**
842	     * Full enrichment pipeline for a monster/NPC.
843	     * Returns stats, drop tables (with sub-tables), and all raw infobox variables.
844	     */
845	    public async enrichMonster(name: string): Promise<WikiPageData> {
846	        const cached = this.readCache('monsters', name);
847	        if (cached && cached.title) {
848	            logger.debug({ name }, 'Monster enrichment served from cache.');
849	            return cached;
850	        }
851	
852	        const monsterMeta = await this.parseMonsterMeta(name);
853	        const dropTables = await this.parseDropTables(name);
854	
855	        const wikitext = await this.getWikitextForName(name);
856	        const rawVariables = wikitext
857	            ? (this.extractTemplate(wikitext, 'Infobox Monster') || {})
858	            : {};
859	
860	        const result: WikiPageData = {
861	            title: name,
862	            fetchedAt: Date.now(),
863	            bonuses: null,
864	            itemMeta: null,
865	            monsterMeta,
866	            dropTables,
867	            rawVariables
868	        };
869	
870	        this.writeCache('monsters', name, result);
871	        return result;
872	    }
873	
874	    /**
875	     * Batch enrichment with progress callback.
876	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
877	     */
878	    public async batchEnrich(
879	        names: string[],
880	        type: 'item' | 'monster',
881	        onProgress?: (current: number, total: number, name: string) => void
882	    ): Promise<Map<string, WikiPageData>> {
883	        const results = new Map<string, WikiPageData>();
884	
885	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
886	
887	        for (let i = 0; i < names.length; i++) {
888	            const name = names[i];
889	            onProgress?.(i + 1, names.length, name);
890	
891	            try {
892	                const data = type === 'item'
893	                    ? await this.enrichItem(name)
894	                    : await this.enrichMonster(name);
895	                results.set(name, data);
896	            } catch (err) {
897	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
898	            }
899	        }
900	
901	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
902	        return results;
903	    }
904	
905	    // ── Integration Helper ─────────────────────────────────
906	
907	    /**
908	     * Converts wiki bonuses into a patch compatible with ItemBook's semanticStats.
909	     * Use this to fill gaps in item_definitions_enriched.json.
910	     */
911	    public toItemBookPatch(bonuses: WikiEquipmentBonuses): Record<string, any> {
912	        const patch: Record<string, any> = {};
913	
914	        if (bonuses.tier > 0) {
915	            const cls = bonuses.class.toLowerCase();
916	            if (cls === 'melee' || bonuses.style === 'slash' || bonuses.style === 'stab' || bonuses.style === 'crush') {
917	                patch.req_attack = bonuses.tier;
918	            } else if (cls === 'ranged') {
919	                patch.req_ranged = bonuses.tier;
920	            } else if (cls === 'magic') {
921	                patch.req_magic = bonuses.tier;
922	            } else if (cls === 'necromancy') {
923	                patch.req_necromancy = bonuses.tier;
924	            }
925	            patch.tier = bonuses.tier;
926	        }
927	
928	        if (bonuses.damage > 0) patch.damage = bonuses.damage;
929	        if (bonuses.accuracy > 0) patch.accuracy = bonuses.accuracy;
930	        if (bonuses.armour > 0) patch.armour = bonuses.armour;
931	        if (bonuses.lifeBonus > 0) patch.lifeBonus = bonuses.lifeBonus;
932	        if (bonuses.prayerBonus > 0) patch.prayerBonus = bonuses.prayerBonus;
933	        patch.slot = bonuses.slot;
934	        patch.style = bonuses.style;
935	        patch.attackSpeed = bonuses.attackSpeed;
936	
937	        return patch;
938	    }
939	
940	    // ── Utilities ──────────────────────────────────────────
941	
942	    private safeInt(value: string): number {
943	        const cleaned = value.replace(/,/g, '').replace(/[^0-9.-]/g, '');
944	        const parsed = parseInt(cleaned, 10);
945	        return isNaN(parsed) ? 0 : parsed;
946	    }
947	
948	    private safeBool(value: string | undefined): boolean {
949	        if (!value) return false;
950	        const lower = value.toLowerCase().trim();
951	        return lower === 'yes' || lower === 'true' || lower === '1';
952	    }
953	
954	    /**
955	     * Session telemetry — how many API calls have been made.
956	     */
957	    public getStats(): { requestCount: number; lastRequest: number } {
958	        return {
959	            requestCount: this.requestCount,
960	            lastRequest: this.lastRequestTime
961	        };
962	    }
963	}
