        gcdTicks: number;          // Confirmed: 3 (1.8s unified)
        enhancedNote: string;
        ultimateNote: string;
    };
    march2026Changes: string[];    // Bullet points from the March 2 2026 patch note
    sourceUrl: string;
    fetchedAt: string;
}

