1035			if (typeof args[1] != "object") { throw new Error("match chunk requires 2n+2 arguments"); }
1036	
1037			const opvalueparser = (args[0] ? buildParser(resolveReference, args[0], typedef) : null);
1038			const conditionstrings = Object.keys(args[1] as any);
1039			const optionvalues = Object.values(args[1] as any).map(q => buildParser(resolveReference, q, typedef))
1040			const conditionparser = conditionParser(resolveReference, conditionstrings);
1041			return r;
1042		},
1043		footer: function (args: any[], parent: any, typedef: any) {
1044			if (args.length != 2) { throw new Error("footer requires length and subtype arguments"); }
1045			const lentype = buildParser(parent, args[0] as any, typedef);
1046			const subtype = buildParser(parent, args[1] as any, typedef);
1047			return {
1048				read(state: DecodeState) {
1049					const len = lentype.read(state);
1050					const oldscan = state.scan;
1051					const footstart = state.endoffset - len;
1052					state.scan = footstart;
1053					if (debugdata) {
1054						debugdata.opcodes.push({ op: `footer`, index: oldscan, stacksize: state.stack.length + 1, jump: { to: footstart } });
1055					}
1056					const res = subtype.read(state);
1057					if (debugdata) {
1058						debugdata.opcodes.push({ op: `footer`, index: state.scan, stacksize: state.stack.length + 1, jump: { to: oldscan } });
1059					}
1060					if (state.scan != state.endoffset) { console.log(`didn't read full footer, ${state.endoffset - state.scan} bytes left`); }
1061					state.scan = oldscan;
1062					state.endoffset = state.endoffset - len;
1063	
1064					return res;
1065				},
1066				write(state: EncodeState, v: any) {
1067					const oldscan = state.scan;
1068					subtype.write(state, v);
1069					const len = state.scan - oldscan;
1070					state.buffer.copyWithin(state.endoffset - len, oldscan, state.scan);
1071					state.scan = oldscan;
1072					state.endoffset -= len;
1073				},
1074				getTypescriptType(indent: string) {
1075					return subtype.getTypescriptType(indent);
1076				},
1077				getJsonSchema() {
1078					return subtype.getJsonSchema();
1079				},
1080			}
1081		},
1082		"tailed varushort": function (args: any, parent: any, typedef: any) {
1083			const overflowchunk = 0x7fff;
1084			return {
1085				read(state: DecodeState) {
1086					let sum = 0;
1087					while (true) {
1088						const byte0 = state.buffer.readUint8(state.scan++);
1089						let v: number;
1090						if ((byte0 & 0x80) == 0) {
1091							v = byte0;
1092						} else {
1093							const byte1 = state.buffer.readUint8(state.scan++);
1094							v = ((byte0 & 0x7f) << 8) | byte1;
1095						}
1096						sum += v;
1097						if (v != overflowchunk) {
1098							return sum;
1099						}
1100					}
1101				},
1102				write(state: EncodeState, v: any) {
1103					if (typeof v != "number") { throw new Error("number expected"); }
1104					while (v >= 0) {
1105						const chunk = Math.min(overflowchunk, v);
1106						if (chunk < 0x80) {
1107							state.buffer.writeUint8(chunk, state.scan++);
1108						} else {
1109							state.buffer.writeUint16BE(chunk | 0x8000, state.scan);
1110							state.scan += 2;
1111						}
1112						v -= chunk;
1113					}
1114				},
1115				getTypescriptType(indent: string) {
1116					return "number";
1117				},
1118				getJsonSchema() {
1119					return { type: "number" };
1120				}
1121			}
1122		},
