1124			return {
1125				read(state: DecodeState) {
1126					const res = {
1127						flags: 0,
1128						shape: null as number | null,
1129						overlay: null as number | null,
1130						settings: null as number | null,
1131						underlay: null as number | null,
1132						height: null as number | null
1133					}
1134					while (true) {
1135						const op = state.buffer.readUint8(state.scan++);
1136						if (op == 0) { break; }
1137						if (op == 1) {
1138							res.height = state.buffer.readUint8(state.scan++);
