1161						+ `${newindent}flags: number,\n`
1162						+ `${newindent}shape: number | null,\n`
1163						+ `${newindent}overlay: number | null,\n`
1164						+ `${newindent}settings: number | null,\n`
1165						+ `${newindent}underlay: number | null,\n`
1166						+ `${newindent}height: number | null,\n`
1167						+ `${indent}}`;
